/* Widows Sons MRA — Chapter Hellas
   The letterhead faces carried into the PDF: Cinzel for the display lines,
   EB Garamond for everything else. Subset to Latin, Greek and Cyrillic, so
   the founding documents set in all three languages of the Chapter.
   Cinzel and EB Garamond are licensed under the SIL Open Font License. */
window.WSFonts = (function(){
  var TTF = {
    'WSGaramond|normal': '',
    'WSGaramond|bold': '',
    'WSGaramond|italic': '',
    'WSCinzel|bold': '',
  };
  function register(doc){
    for(var key in TTF){
      var bits = key.split('|');
      var file = bits[0] + '-' + bits[1] + '.ttf';
      doc.addFileToVFS(file, TTF[key]);
      doc.addFont(file, bits[0], bits[1]);
    }
    return doc;
  }
  return { register:register };
})();
